import fs from 'node:fs/promises';const dir='artifacts/reply-review-20261019-weekend';const form=new FormData();form.append('file',new File([await fs.readFile(dir+'/juliette.wav')],'juliette.wav',{type:'audio/wav'}));form.append('model','whisper-1');form.append('language','en');const r=await fetch('https://api.openai.com/v1/audio/transcriptions',{method:'POST',headers:{Authorization:'Bearer '+process.env.OPENAI_API_KEY.trim()},body:form});if(!r.ok)throw Error('Transcription failed '+r.status);const result=await r.json();await fs.writeFile(dir+'/juliette-transcript.json',JSON.stringify(result,null,2));console.log(result.text);
